import * as React from "react"
import { cn } from "@/lib/utils"

// Campo-slider: una píldora con el nombre adentro y el valor a la derecha.
// Arrastrás de costado en cualquier parte para cambiarlo (Shift = fino). Flechas del teclado.
// Si tiene pocos valores posibles (`step` grande), muestra un punto por cada uno;
// los que quedan debajo del relleno se ven gris oscuro (y del tono fuerte al pasar el mouse o arrastrar).
// La rayita (handle) es siempre del color de la app. Al pasar el mouse o arrastrar,
// el relleno se pinta del color de la app (y la rayita pasa al tono fuerte para que se vea).
// orientation="vertical": la píldora parada; se llena de abajo hacia arriba, el número va
// arriba y el nombre abajo. Con `hideText`, la píldora queda limpia (nombre y valor van afuera). Se arrastra para arriba (más) o para abajo (menos). Alto: h-full o el que le des.

// Puntos debajo del relleno: gris oscuro en reposo; tono fuerte cuando el relleno se pinta (hover / arrastrando)
const FILLED_DOT = (active: boolean) =>
  active
    ? "bg-brand-strong"
    : "bg-muted-foreground group-hover/fs:bg-brand-strong"

const BASE = 0.36 // parte de la píldora que siempre ocupa el relleno (donde va el nombre)

export function FieldSlider({
  label,
  value,
  min,
  max,
  step = 1,
  defaultValue,
  format = String,
  onChange,
  orientation = "horizontal",
  hideText = false,
  className,
}: {
  label: string
  value: number
  min: number
  max: number
  step?: number
  defaultValue?: number
  format?: (v: number) => string
  onChange: (v: number) => void
  orientation?: "horizontal" | "vertical"
  /** sólo vertical: sin texto adentro de la píldora */
  hideText?: boolean
  className?: string
}) {
  const ref = React.useRef<HTMLDivElement>(null)
  const start = React.useRef<{ x: number; v: number } | null>(null)
  const [active, setActive] = React.useState(false)
  const clamp = (v: number) => Math.min(max, Math.max(min, v))
  const snap = (v: number) => Math.round(v / step) * step
  const n = (value - min) / (max - min || 1)
  const positions = Math.round((max - min) / step) + 1
  const showDots = positions <= 12
  const vertical = orientation === "vertical"
  // Vertical: cada valor tiene su lugar a la misma distancia, con el mismo margen (PAD) arriba y abajo.
  // La rayita queda centrada en el lugar del valor y el relleno llega PAD por encima de ella.
  const PAD = hideText ? 20 : 44 // px (con texto, deja lugar para el número y el nombre)
  const at = (p: number) => `calc(${PAD}px + ${p} * (100% - ${2 * PAD}px))`

  const handlers = {
    onPointerDown: (e: React.PointerEvent<HTMLDivElement>) => {
      e.currentTarget.setPointerCapture(e.pointerId)
      start.current = { x: vertical ? e.clientY : e.clientX, v: value }
      setActive(true)
    },
    onPointerMove: (e: React.PointerEvent<HTMLDivElement>) => {
      if (!start.current || !ref.current) return
      const size = vertical
        ? ref.current.offsetHeight - 2 * PAD
        : ref.current.offsetWidth * (1 - BASE)
      const fine = e.shiftKey ? 0.25 : 1
      const d = vertical
        ? start.current.x - e.clientY
        : e.clientX - start.current.x
      onChange(clamp(snap(start.current.v + (d / size) * (max - min) * fine)))
    },
    onPointerUp: () => {
      start.current = null
      setActive(false)
    },
    onPointerCancel: () => {
      start.current = null
      setActive(false)
    },
    onDoubleClick: () => defaultValue !== undefined && onChange(defaultValue),
    onKeyDown: (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (e.key === "ArrowRight" || e.key === "ArrowUp")
        onChange(clamp(snap(value + step)))
      else if (e.key === "ArrowLeft" || e.key === "ArrowDown")
        onChange(clamp(snap(value - step)))
      else return
      e.preventDefault()
    },
  }

  if (vertical) {
    return (
      <div
        ref={ref}
        data-slot="field-slider"
        data-orientation="vertical"
        role="slider"
        tabIndex={0}
        aria-label={label}
        aria-orientation="vertical"
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={value}
        className={cn(
          "group/fs relative flex h-full min-h-48 w-14 cursor-ns-resize touch-none flex-col items-center overflow-hidden rounded-2xl bg-secondary outline-none select-none focus-visible:ring-4 focus-visible:ring-ring/40 in-data-[variant=inset]:bg-card",
          className
        )}
        {...handlers}
      >
        <div
          className={cn(
            "absolute inset-x-0 bottom-0 rounded-2xl transition-colors",
            active
              ? "bg-brand"
              : "bg-muted-foreground/15 group-hover/fs:bg-brand"
          )}
          style={{
            height: `calc(${2 * PAD}px + ${n} * (100% - ${2 * PAD}px))`,
          }}
        >
          <span
            style={{ top: PAD - 1 }}
            className={cn(
              "absolute left-1/2 h-0.5 w-4 -translate-x-1/2 rounded-full transition-colors",
              active
                ? "bg-brand-strong"
                : "bg-brand group-hover/fs:bg-brand-strong"
            )}
          />
        </div>
        {showDots &&
          Array.from({ length: positions }, (_, i) => {
            const p = i / (positions - 1)
            // donde está la rayita no va punto; con número arriba, los dos últimos lugares quedan libres
            if (Math.abs(p - n) < 1e-6 || (!hideText && i >= positions - 2))
              return null
            return (
              <span
                key={i}
                className={cn(
                  "absolute left-1/2 dot -translate-x-1/2 translate-y-1/2 transition-colors",
                  p < n ? FILLED_DOT(active) : "bg-muted-foreground/40"
                )}
                style={{ bottom: at(p) }}
              />
            )
          })}
        {!hideText && (
          <>
            <span className="relative pt-4 font-medium live-number">
              {format(value)}
            </span>
            <span
              className={cn(
                "relative mt-auto pb-3 text-xs transition-colors",
                active
                  ? "text-brand-foreground"
                  : "text-muted-foreground group-hover/fs:text-brand-foreground"
              )}
            >
              {label}
            </span>
          </>
        )}
      </div>
    )
  }

  return (
    <div
      ref={ref}
      data-slot="field-slider"
      role="slider"
      tabIndex={0}
      aria-label={label}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuenow={value}
      className={cn(
        "group/fs relative flex h-12 w-full cursor-ew-resize touch-none items-center overflow-hidden rounded-2xl bg-secondary outline-none select-none focus-visible:ring-4 focus-visible:ring-ring/40 in-data-[variant=inset]:bg-card",
        className
      )}
      {...handlers}
    >
      <div
        className={cn(
          "absolute inset-y-0 left-0 rounded-2xl transition-colors",
          active ? "bg-brand" : "bg-muted-foreground/15 group-hover/fs:bg-brand"
        )}
        style={{ width: `${(BASE + n * (1 - BASE)) * 100}%` }}
      >
        <span
          className={cn(
            "absolute top-1/2 right-3 h-4 w-0.5 -translate-y-1/2 rounded-full transition-colors",
            active
              ? "bg-brand-strong"
              : "bg-brand group-hover/fs:bg-brand-strong"
          )}
        />
      </div>
      {showDots &&
        Array.from({ length: positions }, (_, i) => {
          const p = i / (positions - 1)
          // donde está la rayita no va punto; el último lugar es donde va el número
          if (Math.abs(p - n) < 1e-6 || i === positions - 1) return null
          return (
            <span
              key={i}
              className={cn(
                "absolute top-1/2 dot -translate-1/2",
                p < n ? FILLED_DOT(active) : "bg-muted-foreground/40"
              )}
              style={{ left: `calc(${(BASE + p * (1 - BASE)) * 100}% - 13px)` }}
            />
          )
        })}
      <span
        className={cn(
          "relative pl-4 transition-colors",
          active
            ? "text-brand-foreground"
            : "text-muted-foreground group-hover/fs:text-brand-foreground"
        )}
      >
        {label}
      </span>
      <span className="relative ml-auto pr-4 font-medium live-number">
        {format(value)}
      </span>
    </div>
  )
}

import { Minus, Plus } from "lucide-react"
import { cn } from "@/lib/utils"

// Stepper: − valor +. Para cantidades chicas (repeticiones, compases, cantidad).
// Fondo blanco, borde gris, − y + siempre del color de la app.

export function Stepper({
  value,
  min = -Infinity,
  max = Infinity,
  step = 1,
  format = String,
  onChange,
  label,
  className,
}: {
  value: number
  min?: number
  max?: number
  step?: number
  format?: (v: number) => string
  onChange: (v: number) => void
  label?: string
  className?: string
}) {
  const btn =
    "grid size-10 place-items-center rounded-full text-brand transition-colors outline-none hover:text-brand-strong focus-visible:text-brand-strong active:text-brand-strong disabled:pointer-events-none disabled:opacity-30 [&_svg]:size-3"
  return (
    <div
      data-slot="stepper"
      role="group"
      aria-label={label}
      className={cn("inline-flex h-10 items-center rounded-full border bg-card", className)}
    >
      <button type="button" className={btn} aria-label="Decrease" disabled={value - step < min} onClick={() => onChange(Math.max(min, value - step))}>
        <Minus />
      </button>
      <span className="live-number min-w-6 text-center text-muted-foreground" aria-live="polite">
        {format(value)}
      </span>
      <button type="button" className={btn} aria-label="Increase" disabled={value + step > max} onClick={() => onChange(Math.min(max, value + step))}>
        <Plus />
      </button>
    </div>
  )
}

import { cn } from "@/lib/utils"

// Píldora con opciones: la elegida resaltada en blanco. Es el único componente
// para elegir UNA opción entre pocas o cambiar de vista (15M · 1H, Año · Mes).
// Dos tamaños: normal (44px de alto) y chico (36px), los dos con letra de 14px.

export function Segmented<T extends string | number>({
  options,
  value,
  onChange,
  label,
  size = "default",
  className,
}: {
  options: { value: T; label: string }[]
  value: T
  onChange: (v: T) => void
  label?: string
  size?: "sm" | "default"
  className?: string
}) {
  return (
    <div
      data-slot="segmented"
      role="radiogroup"
      aria-label={label}
      className={cn("inline-flex items-center gap-0.5 rounded-full bg-secondary in-data-[variant=inset]:bg-card", size === "sm" ? "p-[3px]" : "p-1", className)}
    >
      {options.map((o) => {
        const on = o.value === value
        return (
          <button
            key={String(o.value)}
            type="button"
            role="radio"
            aria-checked={on}
            onClick={() => onChange(o.value)}
            className={cn(
              "rounded-full font-medium transition-[color,background-color,box-shadow] outline-none focus-visible:ring-2 focus-visible:ring-ring/50",
              size === "sm" ? "h-[30px] px-3 text-sm" : "h-9 px-4 text-sm",
              on ? "bg-card text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"
            )}
          >
            {o.label}
          </button>
        )
      })}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"
import { Slider } from "@/components/ui/slider"

// Nombre + número editable + slider. Podés escribir el número exacto o arrastrar.

export function NumberSlider({
  label,
  value,
  min,
  max,
  step = 1,
  onChange,
  className,
}: {
  label: string
  value: number
  min: number
  max: number
  step?: number
  onChange: (v: number) => void
  className?: string
}) {
  const [draft, setDraft] = React.useState<string | null>(null)
  const id = React.useId()
  const commit = () => {
    if (draft === null) return
    const v = Number(draft.replace(",", "."))
    if (!Number.isNaN(v)) onChange(Math.min(max, Math.max(min, Math.round(v / step) * step)))
    setDraft(null)
  }
  return (
    <div data-slot="number-slider" className={cn("grid grid-cols-[minmax(0,6rem)_4rem_minmax(0,1fr)] items-center gap-3", className)}>
      <label htmlFor={id} className="truncate text-sm text-muted-foreground">
        {label}
      </label>
      <input
        id={id}
        inputMode="decimal"
        value={draft ?? String(value)}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={commit}
        onKeyDown={(e) => {
          if (e.key === "Enter") (e.target as HTMLInputElement).blur()
          else if (e.key === "Escape") setDraft(null)
          else if (e.key === "ArrowUp") onChange(Math.min(max, value + step))
          else if (e.key === "ArrowDown") onChange(Math.max(min, value - step))
          else return
          e.preventDefault()
        }}
        className="live-number h-9 w-full rounded-full border border-transparent bg-secondary in-data-[variant=inset]:bg-card px-3.5 font-mono text-sm outline-none focus-visible:border-brand"
      />
      <Slider aria-label={label} min={min} max={max} step={step} value={[value]} onValueChange={([v]) => onChange(v)} />
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// Reparto entre dos cosas (ej: CAFÉ 37% | 63% LECHE, o seco/efecto, o izquierda/derecha).
// Arrastrás la rayita del medio. Doble clic = mitad y mitad.
// `value` es la parte de la izquierda, de 0 a 1.
// Si un lado queda muy angosto para leerse, su texto pasa arriba del slider
// (nombre en gris clarito; el número de la izquierda en el color de la app).

export function SplitSlider({
  value,
  onChange,
  left,
  right,
  defaultValue = 0.5,
  className,
}: {
  value: number
  onChange: (v: number) => void
  left: string
  right: string
  defaultValue?: number
  className?: string
}) {
  const dragging = React.useRef(false)
  const [active, setActive] = React.useState(false)
  const n = Math.min(1, Math.max(0, value))
  const setFrom = (e: React.PointerEvent<HTMLDivElement>) => {
    const r = e.currentTarget.getBoundingClientRect()
    onChange(Math.round(Math.min(1, Math.max(0, (e.clientX - r.left) / r.width)) * 100) / 100)
  }
  const pct = (v: number) => `${Math.round(v * 100)}%`
  const leftOut = n < 0.28
  const rightOut = n > 0.72
  const leftText = (
    <>
      <span className="opacity-80">{left}</span>
      <span className="live-number font-semibold">{pct(n)}</span>
    </>
  )
  const rightText = (
    <>
      <span className="live-number font-semibold">{pct(1 - n)}</span>
      <span className="opacity-60">{right}</span>
    </>
  )

  return (
    <div
      data-slot="split-slider"
      role="slider"
      tabIndex={0}
      aria-label={`${left} / ${right}`}
      aria-valuemin={0}
      aria-valuemax={1}
      aria-valuenow={n}
      aria-valuetext={`${left} ${pct(n)}, ${right} ${pct(1 - n)}`}
      className={cn("group/split relative flex h-12 w-full cursor-ew-resize touch-none items-center gap-1.5 font-mono text-sm uppercase outline-none select-none focus-visible:[&>[data-handle]]:bg-brand", className)}
      onPointerDown={(e) => {
        e.currentTarget.setPointerCapture(e.pointerId)
        dragging.current = true
        setActive(true)
        setFrom(e)
      }}
      onPointerMove={(e) => dragging.current && setFrom(e)}
      onPointerUp={() => {
        dragging.current = false
        setActive(false)
      }}
      onPointerCancel={() => {
        dragging.current = false
        setActive(false)
      }}
      onDoubleClick={() => onChange(defaultValue)}
      onKeyDown={(e) => {
        if (e.key === "ArrowRight") onChange(Math.min(1, Math.round((n + 0.01) * 100) / 100))
        else if (e.key === "ArrowLeft") onChange(Math.max(0, Math.round((n - 0.01) * 100) / 100))
        else return
        e.preventDefault()
      }}
    >
      <div
        className={cn("flex h-full min-w-0 items-center gap-2 overflow-hidden rounded-xl bg-brand whitespace-nowrap text-brand-foreground", !leftOut && "px-4")}
        style={{ width: `calc(${n} * (100% - 0.75rem - 4px))` }}
      >
        {!leftOut && leftText}
      </div>
      <div
        data-handle
        className={cn(
          "h-10 w-1 shrink-0 rounded-full transition-colors",
          active ? "bg-brand" : "bg-foreground group-hover/split:bg-brand"
        )}
      />
      <div className={cn("flex h-full min-w-0 flex-1 items-center justify-end gap-2 overflow-hidden rounded-xl bg-secondary in-data-[variant=inset]:bg-card whitespace-nowrap", !rightOut && "px-4")}>
        {!rightOut && rightText}
      </div>
      {leftOut && (
        <div className="absolute bottom-full left-0 mb-2 flex gap-2 whitespace-nowrap">
          <span className="text-muted-foreground">{left}</span>
          <span className="live-number font-semibold text-brand">{pct(n)}</span>
        </div>
      )}
      {rightOut && (
        <div className="absolute right-0 bottom-full mb-2 flex gap-2 whitespace-nowrap">
          <span className="live-number font-semibold">{pct(1 - n)}</span>
          <span className="text-muted-foreground">{right}</span>
        </div>
      )}
    </div>
  )
}

import { cn } from "@/lib/utils"

// Fichas: opciones en cuadraditos separados; la elegida se pinta del color de la app.
// Con `columns`, las fichas son rectángulos que llenan el ancho (y el alto, si le das altura
// al grupo, ej: flex-1 adentro de un AudioPanel), en esa cantidad de columnas.
// Para elegir UNA opción entre pocas cuando cada una es corta (4 · 8 · 5, 3/4 · 4/4).

export function TileGroup<T extends string | number>({
  options,
  value,
  onChange,
  label,
  columns,
  className,
}: {
  options: { value: T; label: string; hint?: string }[]
  value: T
  onChange: (v: T) => void
  label?: string
  columns?: number
  className?: string
}) {
  return (
    <div data-slot="tile-group" role="radiogroup" aria-label={label} className={cn(columns ? "grid auto-rows-fr gap-1.5" : "flex flex-wrap gap-1.5", className)}
      style={columns ? { gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` } : undefined}
    >
      {options.map((o) => {
        const on = o.value === value
        return (
          <button
            key={String(o.value)}
            type="button"
            role="radio"
            aria-checked={on}
            title={o.hint}
            onClick={() => onChange(o.value)}
            className={cn(
              columns ? "h-full min-h-12 w-full" : "h-10 min-w-10",
              "flex items-center justify-center rounded-box-s px-2 text-center text-sm font-medium whitespace-nowrap transition-colors outline-none focus-visible:ring-2 focus-visible:ring-brand",
              on
                ? "bg-brand text-brand-foreground hover:bg-brand-strong"
                : "bg-secondary text-foreground hover:bg-brand hover:text-brand-foreground in-data-[variant=inset]:bg-card in-data-[variant=inset]:hover:bg-brand"
            )}
          >
            {o.label}
          </button>
        )
      })}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// Ficha cuadrada con ícono arriba (16px, color de la app) y nombre abajo.
// Para elegir algo de un catálogo (ej: "agregar un sonido"). Llena su columna:
// ponela en una grilla (grid-cols-3 gap-box-gap) y se vuelve cuadrada sola.
// Al pasar el mouse se pinta del color de la app y el ícono queda blanco.

export function IconTile({
  icon: Icon,
  label,
  className,
  ...props
}: {
  icon: React.ComponentType<{ className?: string }>
  label: React.ReactNode
} & React.ComponentProps<"button">) {
  return (
    <button
      type="button"
      data-slot="icon-tile"
      className={cn(
        "group/tile flex aspect-square min-w-0 cursor-pointer flex-col items-start justify-between rounded-box-s bg-secondary p-box-s text-left text-sm font-medium text-foreground transition-colors outline-none",
        "hover:bg-brand hover:text-brand-foreground active:bg-brand-strong focus-visible:ring-2 focus-visible:ring-brand",
        "in-data-[variant=inset]:bg-card in-data-[variant=inset]:hover:bg-brand",
        className
      )}
      {...props}
    >
      <Icon className="size-4 text-brand group-hover/tile:text-brand-foreground group-active/tile:text-brand-foreground" />
      <span>{label}</span>
    </button>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// Columna para un control vertical (ej: FieldSlider orientation="vertical" hideText):
// nombre y valor arriba, afuera del control; el control llena el alto; botones abajo.
// Con `off`, el valor muestra `offText` y el control se atenúa.

export function FieldColumn({
  label,
  value,
  off,
  offText = "OFF",
  hint,
  buttons,
  className,
  children,
}: {
  label: React.ReactNode
  value: React.ReactNode
  off?: boolean
  offText?: React.ReactNode
  hint?: string
  buttons?: React.ReactNode
  className?: string
  children: React.ReactNode
}) {
  return (
    <div data-slot="field-column" title={hint} className={cn("flex h-full flex-col items-center gap-1", className)}>
      <span className="eyebrow">{label}</span>
      <span className={cn("live-number font-mono text-sm font-semibold", off && "text-muted-foreground")}>{off ? offText : value}</span>
      <div className={cn("my-1 flex min-h-0 flex-1 [&_[data-slot=field-slider]]:min-h-0", off && "pointer-events-none opacity-40")}>{children}</div>
      {buttons}
    </div>
  )
}

import { cn } from "@/lib/utils"

// Tab de ancho completo (diseño de outfit-tracker, con los colores del sistema).
// Para elegir entre MÁS DE 3 opciones (ej: las 6 categorías). Con 2 o 3 opciones
// se usa la píldora con opciones (Segmented).
// Va pegado arriba de una caja: la caja lleva overflow-hidden y la tab ocupa todo el ancho.
// La elegida se pinta del color de la app; las demás quedan en gris.

export function TabBar<T extends string | number>({
  options,
  value,
  onChange,
  label,
  className,
}: {
  options: { value: T; label: string }[]
  value: T
  onChange: (v: T) => void
  label?: string
  className?: string
}) {
  return (
    <div data-slot="tab-bar" role="tablist" aria-label={label} className={cn("flex w-full shrink-0 border-b border-border", className)}>
      {options.map((o, i) => {
        const on = o.value === value
        return (
          <button
            key={String(o.value)}
            type="button"
            role="tab"
            aria-selected={on}
            onClick={() => onChange(o.value)}
            className={cn(
              "flex min-w-0 flex-1 items-center justify-center truncate px-2 py-4 text-sm transition-colors outline-none focus-visible:ring-2 focus-visible:ring-brand focus-visible:ring-inset",
              i < options.length - 1 && "border-r border-border",
              on ? "bg-primary text-primary-foreground" : "bg-card text-muted-foreground hover:text-foreground"
            )}
          >
            {o.label}
          </button>
        )
      })}
    </div>
  )
}
